Declarations.AsyncA38Batch:
public class AsyncA38Batch implements Database.Batchable<Integer>,Database.Stateful,Database.AllowsCallouts {
 public List<Integer> values;
 public Integer total=0;
 public Boolean finished=false;
 public AsyncA38Batch(List<Integer> xs){values=xs;}
 public Iterable<Integer> start(Database.BatchableContext c){return values;}
 public void execute(Database.BatchableContext c,List<Integer> scope){
  for(Integer n:scope) if(n!=null) total+=n;
 }
 public void finish(Database.BatchableContext c){
  finished=true;
  if(c!=null) insert new Account(Name='A38-batch',Description=String.valueOf(total));
 }
 public static Boolean submit(Integer scope){
  Savepoint s=Database.setSavepoint();
  try { return Database.executeBatch(new AsyncA38Batch(new List<Integer>{1}),scope)!=null; }
  finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
 public static Boolean submitNull(){
  Savepoint s=Database.setSavepoint();
  try { return Database.executeBatch(null)!=null; }
  finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
}

