public class AsyncA38Future {
 @future public static void fire(Integer n,String text,List<Integer> xs) {
  insert new Account(Name='A38-future',Description=String.valueOf(n)+'|'+text+'|'+xs);
 }
 @future public static void collections(Set<String> xs,Map<String,Integer> m) {}
 public static void submit(Integer n,String text,List<Integer> xs) {
  Savepoint s=Database.setSavepoint();
  try { fire(n,text,xs); } finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
 public static void submitCollections(Set<String> xs,Map<String,Integer> m) {
  Savepoint s=Database.setSavepoint();
  try { collections(xs,m); } finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
}

