public class AsyncA38Queue implements Queueable {
 public String text;
 public Boolean chain=false;
 public Boolean finalizer=false;
 public AsyncA38Queue(String value){text=value;}
 public void execute(QueueableContext c){
  if(finalizer) System.attachFinalizer(new AsyncA38Finalizer());
  if(chain && c!=null) System.enqueueJob(new AsyncA38Queue('child'));
  if(chain && c==null) {
   Savepoint s=Database.setSavepoint();
   try { System.enqueueJob(new AsyncA38Queue('child')); }
   finally { Database.rollback(s); Database.releaseSavepoint(s); }
  }
  insert new Account(Name='A38-queue',Description=text);
 }
 public static Boolean submitDelay(Integer delay){
  Savepoint s=Database.setSavepoint();
  try { return System.enqueueJob(new AsyncA38Queue('delay'),delay)!=null; }
  finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
 public static Boolean submitOptions(AsyncOptions options){
  Savepoint s=Database.setSavepoint();
  try { return System.enqueueJob(new AsyncA38Queue('options'),options)!=null; }
  finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
}

