 public static Boolean submit(String cron){return submitName('A38-owned-cron',cron);}
 public static Boolean submitName(String name,String cron){
  Savepoint s=Database.setSavepoint();
  try { return System.schedule(name,cron,new AsyncA38Schedule())!=null; }
  finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
 public static Boolean submitDuplicate(){
  Savepoint s=Database.setSavepoint();
  try {
   System.schedule('A38-owned-duplicate','0 0 0 1 1 ? 2099',new AsyncA38Schedule());
   return System.schedule('A38-owned-duplicate','0 0 0 1 1 ? 2099',new AsyncA38Schedule())!=null;
  } finally { Database.rollback(s); Database.releaseSavepoint(s); }
 }
}

